import React, { useState, useEffect } from 'react';
import './Jubilacion.css'; 
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

const Jubilacion = () => {
    const [data, setData] = useState([]);  // Estado para almacenar los datos dinámicos
    const [loading, setLoading] = useState(true);  // Estado de carga
    const apiKey = 'c80584cb38-3c1fd2f449-sk8eb7';  // Tu clave de API

    // Función para obtener los datos desde la API
    const fetchExchangeRateData = async () => {
        try {
            const response = await fetch(
                `https://api.fastforex.io/time-series?from=USD&to=MXN&interval=P1D&api_key=${apiKey}`
            );
            const result = await response.json();

            // Verifica si el resultado tiene los datos que esperas
            console.log("Datos obtenidos de la API:", result);

            // Transformar los datos para usarlos en el gráfico
            const transformedData = Object.keys(result.results.MXN).map(date => ({
                date: date,          // Fecha
                value: result.results.MXN[date],  // Valor de MXN en esa fecha
            }));

            console.log("Datos transformados para el gráfico:", transformedData);

            setData(transformedData);  // Actualizar los datos en el estado
            setLoading(false);  // Desactivar el estado de carga
        } catch (error) {
            console.error('Error fetching exchange rate data:', error);
            setLoading(false);  // Asegurarse de desactivar el estado de carga en caso de error
        }
    };

    // Llamada a la API cuando el componente se monta
    useEffect(() => {
        fetchExchangeRateData();
    }, []);

    return (
        <div className="jubilacion-container">
            <h1 className="jubilacion-title">Predicción de Moneda</h1>
            <div className="jubilacion-content">
                <p>Este gráfico muestra el precio del dólar frente al peso mexicano (MXN).</p>

                {loading ? (
                    <p>Cargando datos...</p>
                ) : (
                    <ResponsiveContainer width="100%" height={400}>
                        <LineChart data={data}>
                            <CartesianGrid strokeDasharray="3 3" />
                            <XAxis dataKey="date" />
                            <YAxis />
                            <Tooltip />
                            <Line type="monotone" dataKey="value" stroke="#007bff" />
                        </LineChart>
                    </ResponsiveContainer>
                )}
            </div>
        </div>
    );
};

export default Jubilacion;
